/* 宽松解析手动输入的日期/时间：2026-09-15 / 2026/9/5 / 20260915 / 2026-09-15 08 / 2026-09-15 08:00 均可
   带时间部分的返回 'YYYY-MM-DD HH:00'，仅日期的返回 'YYYY-MM-DD' */
function sourceParseDateInput(v){
  if(!v) return null;
  v = String(v).trim().replace(/\s+/g,' ');
  let m = v.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})[ T](\d{1,2})(?::(\d{1,2}))?$/);
  if(m) return m[1]+'-'+pad(+m[2])+'-'+pad(+m[3])+' '+pad(+m[4])+':00';
  m = v.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/);
  if(m) return m[1]+'-'+pad(+m[2])+'-'+pad(+m[3]);
  m = v.match(/^(\d{4})(\d{2})(\d{2})$/);
  if(m) return m[1]+'-'+m[2]+'-'+m[3];
  return null;
}
/* 'YYYY-MM-DD HH:00' 级别的时间运算 */
function hourMs(s){ return new Date(+s.slice(0,4), +s.slice(5,7)-1, +s.slice(8,10), +s.slice(11,13)).getTime(); }
function shiftHour(s, n){
  const d = new Date(hourMs(s) + n*3600000);
  return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+' '+pad(d.getHours())+':00';
}
function hoursBetween(a,b){ return Math.round((hourMs(b)-hourMs(a))/3600000); }
/* 自定义输入里的小时下拉（按小时粒度时出现） */
function hourOpts(v){
  const hh = v && v.length>=13 ? +v.slice(11,13) : null;
  let o='';
  for(let i=0;i<24;i++) o += `<option value="${pad(i)}"${hh===i?' selected':''}>${pad(i)}</option>`;
  return o;
}

