function shiftDate(ds, days){ const p=ds.split('-').map(Number); const d=new Date(p[0],p[1]-1,p[2]);
  d.setDate(d.getDate()+days); return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate()); }
