function queriedRows(hour){
 const r=scope.summary,q=currentSelection(),p=KEY==='RS'?r?.profile?.supplement:r?.profile?.primary;
 if(exactPermissionDenied()||KEY==='RS'&&!rsSame(r?.query,q)||r?.profile?.key!==KEY||!['start','end','grain'].every(k=>r.query?.[k]===q[k])||p?.status!=='available'||p.seriesGranularity!=='day-or-hour'||p.labelsVerified!==true)return [];
 const rows=new Map();
 for(const row of p.rows||[]){
  if(typeof row.date!=='string'||!/^\d{4}-\d{2}-\d{2}( \d{2}:00)?$/.test(row.date)||!Number.isSafeInteger(row.orders)||row.orders<0||typeof row.amount!=='number'||!Number.isFinite(row.amount))return [];
  const stamp=row.date.length===10?row.date+' 00:00':row.date;
  if(stamp<p.period.start||stamp>=p.period.end){if(row.orders===0&&row.amount===0)continue;return [];}
  if(hour&&row.date.length!==16)return [];
  const key=hour?row.date:row.date.slice(0,10),target=rows.get(key)||{date:key,ts:key,orders:0,amount:0};target.orders+=row.orders;target.amount+=row.amount;rows.set(key,target);
 }
 return [...rows.values()].sort((a,b)=>a.date.localeCompare(b.date)).map(r=>({...r,amount:Math.round(r.amount*100)/100}));
}


