/* ---------------- 分时（小时）口径 ----------------
   实测（2026-09-21，用 MMOEXP 反证 3 天窗口，单量与金额逐日精确吻合）：
     · 小时桶的标签是**北京时间整点**（00:00 ~ 23:00）
     · 日粒度桶的标签是**UTC 日**，即日桶 D 实际覆盖北京 [D 08:00, D+1 07:59]
   所以要把分时和对得上的「销售日历」对齐，需把整点 -8h 归档：
     北京 hh>=08 归入日 D=当天；hh<08 归入日 D=前一天；组内序号 =(hh-8+24)%24。
   勾掉「对齐」即按后台原始整点展示（与后台界面一致）。 */
function hourDayOf(ts){return ts.slice(0,10);}
function hourIdxOf(ts){return +ts.slice(11,13);}
function hourLabel(ts){ return hourDayOf(ts) + ' ' + pad(hourIdxOf(ts)) + ':00'; }
/* 按「小时跨度」取窗口（k=0 表示全部）；稀疏小时目标也按真实时间切 */
function hourWindow(k){
  const q=currentSelection(),a=hourlyAll().filter(r=>r.ts.slice(0,10)>=q.start.slice(0,10)&&r.ts.slice(0,10)<=q.end.slice(0,10));
  if(!a.length || k===0) return a;
  const lo = shiftHour(a[a.length-1].ts, -(k-1));
  return a.filter(r => r.ts >= lo);
}
function hourlyRows(){ return hourWindow(HRANGE); }

