function pfNode(key){ return (PROFIT.profiles || {})[key || KEY] || null; }
function monthEnd(ms){ const q=ms.split('-').map(Number); return ms+'-'+pad(new Date(q[0],q[1],0).getDate()); }
function profitReady(){ return !!(PROFIT.profiles && Object.keys(PROFIT.profiles).length); }

/* 区间内的利润率聚合：[a,b] 为 YYYY-MM-DD；daySet 非空时按「日期集合」取（小时粒度用）
   ⚠ 带 z 标记的桶 = 后台那天「利润率 0% + 货款 0」= 缺成本数据，不是真的 0% 利润，
     必须从「率的分子分母」里剔除（金额仍然照算，因为它确实是当天的销售额）。 */
function profitAgg(key, a, b, daySet){
  const n = pfNode(key);
  if(!n) return null;
  const dl = n.daily||[], ml = n.monthly||[];
  const o = {rate:null, amt:0, amtR:0, ord:0, wsum:0, nb:0, skip:0, months:0, partial:false,
             covA:null, covB:null};
  const dmin = dl.length ? dl[0].d : null, dmax = dl.length ? dl[dl.length-1].d : null;
  const use = x => {
    const A = x.a||0;
    o.amt += A; o.nb++;
    /* 记录「真正纳入计算」的桶覆盖范围：早于逐日窗口的区间会被月桶规则挡掉，
       副标题据此提示「实际自 X 起」，避免静默少算 */
    const bA = x.d || (x.m ? x.m+'-01' : null);
    const bB = x.d || (x.m ? monthEnd(x.m) : null);
    if(bA && (!o.covA || bA < o.covA)) o.covA = bA;
    if(bB && (!o.covB || bB > o.covB)) o.covB = bB;
    if(x.z){ o.skip++; return; }
    o.amtR += A; o.ord += (x.o||0); o.wsum += A*(x.r||0);
  };
  if(daySet){ dl.forEach(x=>{ if(daySet.has(x.d)) use(x); }); }
  else      { dl.forEach(x=>{ if(x.d>=a && x.d<=b) use(x); }); }
  ml.forEach(x=>{
    const ms = x.m+'-01', me = monthEnd(x.m);
    if(me<a || ms>b) return;                                    /* 完全不相交 */
    if(dmin && dmax && !(me<dmin || ms>dmax)) return;            /* 与逐日窗口重叠 → 交给逐日，避免重复计数 */
    if(ms<a || me>b){ o.partial = true; return; }                /* 只覆盖部分月 → 无法拆分，标注但不计入 */
    use(x); o.months++;
  });
  o.rate = o.amtR ? o.wsum/o.amtR : null;
  return o;
}

/* 预设区间（今日 / 近7 / 近14 / 近30）后台自己算的原值 —— 比加权推算准，优先用 */
function profitExact(a, b){
  const n = pfNode();
  if(!n || !n.ranges) return null;
  for(const k in n.ranges){
    const x = n.ranges[k];
    if(x && x.s===a && x.e===b && x.r!=null) return x;
  }
  return null;
}

/* 当前区间的聚合 + 上一等长区间（用于环比） */
function profitCtx(){
 const q=currentSelection();if(!q.start||!q.end||q.grain==='hour')return null;
 const a=q.start,b=q.end,cur=profitAgg(KEY,a,b,null);
 return {a,b,span:Math.round((Date.parse(b)-Date.parse(a))/86400000)+1,daySet:null,cur,prev:null,totalAmt:null};
}

function profitSeriesInRange(ctx){
  const n = pfNode(); if(!n) return [];
  const dl = n.daily||[], ml = n.monthly||[];
  const dmin = dl.length ? dl[0].d : null, dmax = dl.length ? dl[dl.length-1].d : null;
  const pick = [];
  if(ctx.daySet){ dl.forEach(x=>{ if(ctx.daySet.has(x.d)) pick.push({k:x.d,lab:x.d.slice(5),o:x.o,a:x.a,r:x.r,z:x.z,u:'日'}); }); }
  else         { dl.forEach(x=>{ if(x.d>=ctx.a && x.d<=ctx.b) pick.push({k:x.d,lab:x.d.slice(5),o:x.o,a:x.a,r:x.r,z:x.z,u:'日'}); }); }
  ml.forEach(x=>{
    const ms = x.m+'-01', me = monthEnd(x.m);
    if(me<ctx.a || ms>ctx.b) return;
    if(dmin && dmax && !(me<dmin || ms>dmax)) return;
    if(ms<ctx.a || me>ctx.b) return;
    pick.push({k:ms, lab:x.m, o:x.o, a:x.a, r:x.r, z:x.z, u:'月'});
  });
  pick.sort((p,q)=> p.k<q.k ? -1 : (p.k>q.k ? 1 : 0));
  return pick;
}

