function fcRiskOverview(d){
 const r=d.current_risks,ready=r&&['available','partial'].includes(r.status);
 const count=v=>Number.isSafeInteger(v)&&v>=0?String(v):'暂缺';
 const amount=v=>typeof v==='number'&&Number.isFinite(v)&&v>=0?fcMoney(v):'金额暂缺';
 const summary=m=>!ready||!m?'合计暂缺':`${m.orders==null?'已知 ':''}${count(m.orders??m.known_orders)} 单 · ${amount(m.amount_usd??m.known_amount_usd)}${m.amount_usd==null&&m.known_amount_usd!=null?'（已知金额）':''}`;
 const missing=m=>'涉及订单额，不是损失'+(ready&&m&&m.missing_amount_orders>0?`；缺金额 ${count(m.missing_amount_orders)} 单`:'');
 const high=typeof r?.high_amount_usd==='number'&&Number.isFinite(r.high_amount_usd)?`高金额未结案（≥${fcMoney(r.high_amount_usd)}）`:'高金额未结案';
 const waitingNote=['按付款时间起算，非 SLA 判定'];
 if(ready&&r.waiting24?.missing_amount_orders>0)waitingNote.push(`缺金额 ${count(r.waiting24.missing_amount_orders)} 单`);
 if(ready&&r.aging?.unknown_time>0)waitingNote.push(`时间暂缺 ${count(r.aging.unknown_time)} 单，未判定账龄`);
 const groups=[['当前问题单',r?.issues,missing(r?.issues)],['待交付 · 等待至少24小时',r?.waiting24,waitingNote.join('；')],[high,r?.high_amount,ready&&r.high_amount?.unknown_selection_orders>0?`另有 ${count(r.high_amount.unknown_selection_orders)} 单缺金额，未判定是否高金额`:'包含当前资金待处理状态']];
 const rows=groups.map(([label,m,note])=>`<div><b>${esc(label)}</b><span>${esc(summary(m))}</span></div><p class="fc-subtle">${esc(note)}</p>`).join('');
 const aging=ready&&r.aging?`<p class="fc-subtle">待交付账龄：&lt;24h ${count(r.aging.under24)} 单 · 24–72h ${count(r.aging['24to72'])} 单 · ≥72h ${count(r.aging.at_least72)} 单 · 时间暂缺 ${count(r.aging.unknown_time)} 单；其中 ${count(r.aging.created_time_fallback)} 单回退下单时间。</p>`:'';
 const captured=Number.isFinite(Date.parse(r?.as_of))?new Date(r.as_of).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'时点暂缺';
 return `<div class="fc-site-groups" data-fc-current-risks>${rows}</div>${aging}<p class="fc-subtle">${ready?'Admin 当前运营状态 · 读取 '+esc(captured):'当前池完整性或新汇总暂缺'}；不受所选支付日期限制。三组可重叠，不相加。</p><button type="button" data-fc-backlog>查看当前待跟进订单 →</button>`;
}
